insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 23, 'E havia uma porta do pátio interior que ficava em frente da porta ao norte; e assim também [outra] ao oriente; e mediu de porta a porta cem côvados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 24, 'Então me levou em direção ao sul, e eis que havia uma porta para o sul; e mediu seus pilares e seu pórtico, conforme a estas medidas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 25, 'E também tinha janelas, assim com havia janelas no seu pórtico em redor; o comprimento era de cinquenta côvados, e a largura de vinte e cinco côvados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 26, 'E suas subidas eram de sete degraus, com seu pórtico diante deles; e tinha palmeiras de um lado e do outro em seus pilares.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 27, 'Também havia uma porta no pátio interior voltada para o sul; e mediu de porta a porta para o sul, cem côvados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 28, 'Então ele me levou ao pátio interior pela porta do sul; e mediu a porta do sul conforme a estas medidas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 29, 'E suas câmaras pequenas, e seus pilares e seu pórtico eram conforme a estas medidas; e também tinham janelas ao redor de seus alpendres; o comprimento era de cinquenta côvados, e de a largura de vinte e cinco côvados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 30, 'E o pórtico em redor era de vinte e cinco côvados de comprimento e cinco côvados de largura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 31, 'E seu pórtico estava no pátio externo, com palmeiras em seus pilares; e suas subidas eram de oito degraus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 32, 'Depois me levou ao pátio interior, para o oriente, e mediu a porta conforme a estas medidas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 33, 'Assim como suas câmaras pequenas, seus pilares, e seu pórtico, conforme a estas medidas; e também tinha suas janelas ao redor de seu pórtico; o comprimento era de cinquenta côvados, e a largura de vinte e cinco côvados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 34, 'E seu pórtico estava no pátio externo, com palmeiras em seus postes de um lado e do outro; e suas subidas eram de oito degraus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 35, 'Então me levou à porta do norte, e mediu conforme a estas medidas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 36, 'Suas câmaras pequenas, seus pilares, e seus arcos, também tinham janelas ao redor; o comprimento era de cinquenta côvados, e a largura de vinte e cinco côvados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 37, 'E seus pilares estavam no pátio exterior, com palmeiras em seus pilares de um lado e do outro; e suas subidas eram de oito degraus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 38, 'E sua câmara e sua porta estavam junto dos pilares das portas, onde lavavam o holocausto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 39, 'E no pórtico da porta havia duas mesas da um lado, e outras duas do outro, para nelas degolar o holocausto, o sacrifício pelo pecado, e o [sacrifício] pela culpa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 40, 'E ao lado de fora da subida para a entrada da porta do norte havia duas mesas; e do outro lado que estava no pórtico da porta, havia duas mesas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 41, 'Quatro mesas de um lado, e quatro mesas do outro lado, junto à porta; oito mesas, sobre as quais degolavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 42, 'E as quatro mesas para o holocausto eram de pedras lavradas, de um côvado e meio de comprimento, e um côvado e meio de largura, e um côvado de altura; sobre elas eram postos os instrumentos com que degolavam a oferta de queima e o sacrifício.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 43, 'E havia ganchos de um palmo, dispostos por dentro ao redor; e sobre as mesas a carne da oferta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 44, 'E de fora da porta interior estavam as câmaras dos cantores no pátio de dentro que era do lado da porta do norte; as quais estavam voltadas para o sul; uma estava ao lado da porta do oriente que estava voltada para o norte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 45, 'E me falou: Esta câmara que está voltada para o sul é para os sacerdotes que têm a guarda do templo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 46, 'Mas a câmara que está voltada para o norte é para os sacerdotes que têm a guarda do altar; estes são os filhos de Zadoque, dentre os filhos de Levi os que se achegam ao SENHOR, para o servir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 47, 'E mediu o pátio, cem côvados de comprimento, e cem côvados de largura, quadrado; e o altar estava diante do templo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 48, 'Então ele me levou ao pórtico do templo, e mediu [cada] pilar do pórtico, cinco côvados de um lado, e cinco côvados do outro; e a largura da porta [era] três côvados de um lado, e três côvados do outro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 40, 49, 'O comprimento do pórtico era vinte côvados, e a largura onze côvados; e era com degraus, pelos quais se subia; e havia colunas junto aos pilares, uma de um lado, e outra do outro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 41, 1, 'Então ele me levou ao templo e mediu os pilares, seis côvados a largura de um lado, e seis côvados do outro, que era a largura da tenda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 41, 2, 'E a largura da entrada era de dez côvados; e os lados da entrada, de cinco côvados de um lado, e cinco do outro. Também mediu seu comprimento de quarenta côvados, e a largura de vinte côvados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 41, 3, 'Então entrou, e mediu o pilar da entrada de dois côvados, e a entrada de seis côvados; e a largura da entrada de sete côvados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 41, 4, 'Também mediu seu comprimento, de vinte côvados, e a largura de vinte côvados, diante do templo; e me disse: Este é o Santo dos Santos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 41, 5, 'Depois mediu a parede do templo, de seis côvados; e quatro côvados era a largura das câmaras que ficavam de lado ao redor do templo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 41, 6, 'E as câmaras laterais eram em três andares câmara sobre câmara, e havia trinta para cada andar; e havia apoios na parede ao redor do templo, sobre os quais as câmaras se apoiavam, pois não se apoiavam na parede do templo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 41, 7, 'E havia maior largura nas câmaras laterais mais para cima, pois o entorno do templo subia de andar em andar ao redor do templo; por isso o templo era mais largo acima; e se subia da câmara baixa se subia à alta pela do meio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 41, 8, 'E olhei para a altura da casa ao redor; os fundamentos das câmaras laterais eram de uma cana inteira de seis côvados maiores de tamanho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 41, 9, 'A largura da parede das câmaras externas era de cinco côvados, e o espaço que restava era o lugar das câmaras laterais que eram junto ao templo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 41, 10, 'E entre as câmaras havia a largura de vinte côvados ao redor do templo por todos os lados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 41, 11, 'E as entradas de cada câmara [estavam voltadas] para o espaço vazio; uma entrada para o norte, e outra entrada para o sul; e a largura do espaço vazio era de cinco côvados ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 41, 12, 'E o edifício que estava diante do lugar separado ao lado do ocidente era da largura de setenta côvados; e a parede do edifício era de cinco côvados de largura ao redor, e seu comprimento era de noventa côvados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 41, 13, 'E mediu o templo, cem côvados de comprimento; e o lugar separado, e o edifício, e suas paredes, de comprimento de cem côvados;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 41, 14, 'E a largura da dianteira do templo, e do lugar separado ao oriente, era de cem côvados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 41, 15, 'Também mediu o comprimento do edifício que estava diante do lugar separado que estava detrás dele, e suas galerias de um lado e do outro eram de cem côvados, com o templo interno, e o pórtico do pátio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 41, 16, 'Os umbrais, e as janelas estreitas, e as galerias ao redor dos três andares, de frente ao umbral, estavam cobertas de madeira ao redor, desde o chão até as janelas; e as janelas estavam cobertas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 41, 17, 'Até o que havia acima da porta, e até o templo interior e exterior, e até toda a parede em redor, por dentro e por fora, [tudo] por medida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 41, 18, 'E era feita com querubins e palmeiras, de maneira que [cada] palmeira ficava entre um querubim e outro; e cada querubim tinha dois rostos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 41, 19, 'Um rosto de homem voltado para palmeira da uma lado, e um rosto de leão voltado para a palmeira do outro lado, [assim era] por todo o templo ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 41, 20, 'Desde o chão até encima da entrada foram feitos os querubins e as palmeiras, e também por toda a parede do templo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 41, 21, 'Os umbrais do templo eram quadrados; e a dianteira do santuário tinha a aparência como a da outra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 41, 22, 'O altar de madeira era de três côvados de altura, e seu comprimento de dois côvados; e seus cantos, seu comprimento, e suas laterais eram de madeira. E ele me falou: Esta é a mesa que está diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 41, 23, 'E o templo e o santuário, [ambos] tinham duas portas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 41, 24, 'E em cada portada havia duas divisões que podiam se virar; duas divisões em uma porta, e duas na outra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 41, 25, 'E nelas, nas portas do templo, foram feitos querubins e palmeiras, assim como estavam feitos nas paredes; e havia uma viga espessa de madeira na dianteira do pórtico por fora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 41, 26, 'E havia janelas estreitas e palmeiras de um lado e do outro, pelas laterais do pórtico, assim como nas câmaras laterais do templo, e nas vigas espessas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 42, 1, 'Depois disto ele me fez sair para o pátio externo, para o lado norte, e me levou às câmaras que estavam de frente ao lugar vazio, e que estavam de frente ao edifício [voltado] para o norte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 42, 2, 'Pela frente à entrada do norte o comprimento era de cem côvados, e a largura era de cinquenta côvados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 42, 3, 'Em frente dos vinte [côvados] que tinha no átrio de dentro, e em frente do solado que tinha o pátio exterior, havia galerias de frente umas às outras em três andares.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 42, 4, 'E diante das câmaras havia um corredor de dez côvados de largura, do lado de dentro, com um caminho de um côvado; e suas entradas para o norte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 42, 5, 'E as câmaras de cima eram mais estreitas, pois as galerias eram mais altas que as outras, [isto é] , que as de baixo, e que as do andar do meio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 42, 6, 'Porque elas estavam em três [andares] , porém não tinham colunas como as colunas dos pátios; por isso eram mais estreitas que as de baixo e as do meio, desde o chão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 42, 7, 'E o muro que estava por fora de frente às câmaras, voltado para o pátio exterior diante das câmaras, tinha cinquenta côvados de comprimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 42, 8, 'Porque o comprimento das câmaras do pátio de fora era de cinquenta côvados; e eis que de frente ao templo havia cem côvados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 42, 9, 'E debaixo destas câmaras estava a entrada do oriente, para entrar nelas do pátio de fora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 42, 10, 'Na largura do muro do pátio ao oriente, diante do lugar vazio, e diante do edifício, havia câmaras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 42, 11, 'E o caminho que havia diante delas era semelhante ao das câmaras que estavam ao norte, conforme seu comprimento, assim como sua largura; e todas as suas saídas eram conforme suas formas e conforme suas entradas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 42, 12, 'E conforme as entradas das câmaras que estavam para o sul, havia [também] uma entrada no princípio do caminho, do caminho diante do muro direito para o oriente, quando se entra por elas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 42, 13, 'Então ele me disse: As câmaras do norte e as câmaras do sul, que estão diante do lugar vazio, elas são câmaras santas, nas quais os sacerdotes que se achegam ao SENHOR comerão as coisas mais santas; ali porão as coisas mais santas, e as ofertas de alimento, e a expiação pelo pecado e a pela culpa; pois o lugar é santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 42, 14, 'Quando os sacerdotes entrarem, não sairão do lugar santo para o pátio de fora; em vez disso, ali deixarão suas vestes com que tenham ministrado, porque são santas; e se vestirão com outras vestes, e [assim] se achegarão ao que é do povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 42, 15, 'E quando acabou de medir o templo interno, ele me tirou pelo caminho da porta que estava voltada para o oriente, e o mediu em redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 42, 16, 'Mediu o lado oriental com a cana de medir, quinhentas canas da cana de medir em redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 42, 17, 'Mediu ao lado do norte, quinhentas canas da cana de medir em redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 42, 18, 'Mediu ao lado do sul, quinhentas canas da cana de medir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 42, 19, 'Rodeou ao lado do ocidente, [e] mediu quinhentas canas da cana de medir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 42, 20, 'Aos quatro lados o mediu; [e] havia um muro ao redor com quinhentas canas de comprimento, e quinhentas canas de largura, para fazer separação entre o santo e o profano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 43, 1, 'Então ele me levou-me à porta; a porta que está voltada para oriente;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 43, 2, 'E eis que a glória do Deus de Israel vinha desde o caminho do oriente; e seu som era como o som de muitas águas, e a terra resplandeceu por causa de sua glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 43, 3, 'E a aparência da visão que vi era como a visão que eu tinha visto quando vim para destruir a cidade; e as visões eram como a visão que vi junto ao rio de Quebar; e caí sobre meu rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 43, 4, 'E a glória do SENHOR entrou no templo [pelo] caminho da porta que estava voltada para o oriente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 43, 5, 'Então o Espírito me ergueu, e me levou ao pátio interno; e eis que a glória do SENHOR encheu o templo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 43, 6, 'E ouvi um que falava comigo desde o templo; e um homem estava em pé junto a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 43, 7, 'E disse-me: Filho do homem, este é o lugar de meu trono, e o lugar das plantas de meus pés, onde habitarei no meio dos filhos de Israel para sempre; e a nação de Israel nunca mais contaminará meu santo nome, [nem] eles, nem seus reis, com suas prostituições, e com seus cadáveres de seus reis em seus altos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 43, 8, 'Quando colocavam o umbral deles junto a meu umbral, e o batente deles junto a meu batente, e era uma parede entre mim e eles; e contaminaram meu santo nome com suas abominações que fizeram; por isso eu os consumi em minha ira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 43, 9, 'Agora lançaram longe de mim sua prostituição e os cadáveres de seus reis; e habitarei no meio deles para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 43, 10, 'Tu, filho do homem, mostra à nação de Israel este templo, para que se envergonhem de suas maldades, e tenham a medida do modelo [do templo] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 43, 11, 'E se eles se envergonharem de tudo quanto fizeram, faze-lhes saber a forma da casa, e seu modelo, e suas saídas e suas entradas, e todas as suas formas, e todas os seus estatutos, e todas as suas formas, e todas as suas leis; e escreve diante de seus olhos, para que guardem toda a sua forma e todos os seus estatutos, e os façam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 43, 12, 'Esta é a lei do templo: sobre o cume do monte, todo o seu contorno em redor será santíssimo. Eis que esta é a lei do templo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 43, 13, 'E estas são as medidas do altar em côvados (o côvado de um côvado e um palmo). A base, de um côvado [de altura] e de um côvado de largura; e o contorno de sua borda ao redor, de um palmo. Este será o fundamento do altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 43, 14, 'E desde a base [de sobre] o chão até a aresta inferior, dois côvados, e a largura de um côvado; e desde a aresta menor até a aresta maior, quatro côvados, e a largura de um côvado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 43, 15, 'E a fornalha do altar, de quatro côvados, e da fornalha do altar para cima havia quatro pontas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 43, 16, 'E o altar tinha doze [côvados] de comprimento e doze de largura, quadrado em seus quatro lados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 43, 17, 'E a aresta, de catorze [côvados] de comprimento e catorze de largura em seus quatro lados; e o contorno ao redor dela era de meio côvado, e a base dela de um côvado em redor; e seus degraus estavam voltados para o oriente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 43, 18, 'E ele me disse-me: Filho do homem, assim diz o Senhor DEUS: Estes são os estatutos do altar, no dia em que ele for feito, para sobre ele oferecer holocausto, e para espargir sangue sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 43, 19, 'E aos sacerdotes Levitas que são da descendência de Zadoque, que se achegam a mim, diz o Senhor DEUS, para me servirem, tu darás um bezerro, filho de vaca, para expiação pelo pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 43, 20, 'E tomarás de seu sangue, e porás nas pontas [do altar] , e nas quatro esquinas da aresta, e no contorno ao redor; assim o limparás e o expiarás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 43, 21, 'Então tomarás o bezerro da expiação pelo pecado, e o queimarão no lugar [específico] do templo, fora do santuário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 43, 22, 'E no segundo dia oferecerás um bode macho sem defeito, para expiação pelo pecado; e purificarão o altar como o purificaram com o bezerro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 43, 23, 'Quando tu acabares de expiar, oferecerás um bezerro sem defeito, filhote de vaca , e um carneiro sem defeito do rebanho;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 43, 24, 'E tu os oferecerás diante do SENHOR; e os sacerdotes lançarão sal sobre eles, e os oferecerão como holocausto ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 43, 25, 'Por sete dias prepararás um bode macho em cada dia de purificação; também prepararão um bezerro filhote de vaca, e um carneiro do rebanho, [todos] sem defeito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 43, 26, 'Por sete dias expiarão o altar, e [o] purificarão; e eles o consagrarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 43, 27, 'E quando eles acabarem estes dias será ao oitavo dia; e dali em adiante, os sacerdotes prepararão sobre o altar vossos sacrifícios de queima e vossas ofertas de gratidão; e eu vos aceitarei, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 1, 'Então ele me fez voltar ao caminho da porta de fora do santuário, a qual estava voltada para o oriente; e ela estava fechada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 2, 'E o SENHOR me disse: Esta porta estará fechada; não se abrirá, nem ninguém entrará por ela, porque o SENHOR Deus de Israel entrou por ela; por isso estará fechada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 3, 'O príncipe; [somente] o príncipe, ele se sentará nela, para comer pão diante do SENHOR; pelo caminho do pórtico da porta entrará, e pelo mesmo caminho sairá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 4, 'Depois me levou pelo caminho da porta do norte, diante da casa; e olhei, e eis que a glória do SENHOR havia enchido a casa do SENHOR; então caí sobre meu rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 5, 'E o SENHOR me disse: Filho do homem, presta atenção, olha com teus olhos, e ouve com teus ouvidos tudo quanto eu falar contigo sobre todas os estatutos da casa do SENHOR, e todas as suas leis; e presta atenção na entrada da casa, e em todas as saídas do santuário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 6, 'E dize aos rebeldes, à casa de Israel: Assim diz o Senhor DEUS: Já basta de todas as vossas abominações, ó casa de Israel!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 7, 'Pois trouxestes estrangeiros, incircuncisos de coração e incircuncisos de carne, para estarem em meu santuário, para profanarem minha casa; pois oferecestes meu pão, a gordura e o sangue; e invalidaram meu pacto, por causa de todas as vossas abominações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 8, 'E não mantivestes a ordem de minhas coisas sagradas; em vez disso pusestes por vós mesmos guardas [estrangeiros] para minha ordem em meu santuário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 9, 'Assim diz o Senhor DEUS: Nenhum estrangeiro, incircunciso de coração e incircunciso de carne, entrará em meu santuário, dentre todos os estrangeiros que estão entre os filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 10, 'Mas os Levitas que se afastaram para longe de mim, que se desviaram de mim para seguirem seus ídolos, quando Israel se desviou, esses levarão sobre si sua maldade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 11, 'Contudo serão trabalhadores em meu santuário, [como] porteiros às portas da casa, e servirão na casa; eles degolarão o holocausto e o sacrifício para o povo, e estarão diante deles para os servirem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 12, 'Pois os serviram diante de seus ídolos, e foram tropeço de maldade para a casa de Israel; por isso jurei de mão levantada contra eles, diz o Senhor DEUS, que levarão sua iniquidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 13, 'E não se achegarão a mim para serem meus sacerdotes, nem se achegarão a nenhuma de minhas coisas sagradas; às coisas santíssimas; em vez disso levarão sobre si sua vergonha e suas abominações que fizeram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 14, 'Portanto os porei por guardas da ordem da casa, em todo o seu serviço, e em tudo o que houver de se fazer nela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 15, 'Mas os sacerdotes Levitas, filhos de Zadoque, que guardaram a guarda de meu santuário quando os filhos de Israel se desviaram de mim, eles se achegarão a mim para me servirem; e estarão diante de mim para me oferecerem a gordura e o sangue, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 16, 'Eles entrarão em meu santuário, e eles se achegarão à minha mesa para me servirem; e guardarão minha ordem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 17, 'E será que, quando entrarem pelas portas do pátio interno, se vestirão de vestes de linho; não haverá sobre eles lã, quando servirem nas portas do pátio interno, e no interior.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 18, 'Turbantes de linho estarão em suas cabeças, e calções de linho sobre seus lombos; não se vestirão [com algo que lhes cause] suor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 19, 'E quando eles saírem ao pátio de fora, ao pátio de fora ao povo, despirão suas vestes com que eles prestaram serviço, as deixarão nas câmaras do santuário, e se vestirão de outras vestes, para que não santifiquem ao povo com suas vestes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 20, 'E não raparão sua cabeça, nem deixarão crescer o cabelo; mas sim apararão o [cabelo] de suas cabeças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 21, 'E nenhum dos sacerdotes beberá vinho quando forem entrar no pátio interno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 22, 'Não tomarão por mulheres nem viúva, nem divorciada, mas sim tomarão virgens da descendência da casa de Israel, ou viúva que for viúva de sacerdote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 23, 'E ensinarão meu povo [a fazer diferença] entre o santo e o profano, e lhes farão saber [a diferença] entre o impuro e o puro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 24, 'E na disputa judicial eles estarão para julgar; conforme meus juízos o julgarão; e guardarão minhas leis e meus estatutos em todas as minhas solenidades, e santificarão meus sábados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 25, 'E não chegarão perto de pessoa alguma morta para se contaminarem; apenas pelo pai, mãe, filho, filha, irmão, ou irmã que não tenha tido marido, é que poderão se contaminar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 26, 'E depois de sua purificação lhe contarão sete dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 27, 'E no dia que ele entrar no lugar santo, no pátio interno, para prestar serviço no lugar santo, oferecerá sua expiação pelo pecado, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 28, 'E [isto] lhes será por herança: eu serei sua herança; por isso não lhes dareis propriedade [de terra] em Israel; eu sou a propriedade deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 29, 'Comerão a oferta de alimentos e o sacrifícios pelo pecado e pela culpa; e toda coisa dedicada em Israel pertencerá a eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 30, 'E as primícias de todos os primeiros frutos de tudo, e toda oferta de tudo o que se oferecer de todas as vossas ofertas, pertencerá aos sacerdotes; dareis também as primícias de todas vossas massas ao sacerdote, para que faça repousar a bênção em tua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 44, 31, 'Os sacerdotes não poderão comer coisa alguma morta por si mesma ou despedaçada, tanto de aves como de animais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 45, 1, 'E quando repartirdes por sortes a terra em herança, proporcionareis uma oferta ao SENHOR: um lugar santo na terra; o comprimento será de vinte e cinco mil canas, e a largura de dez mil; este será santificado em todo o seu contorno ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 45, 2, 'Deste [terreno] serão para o santuário quinhentas [canas] de comprimento, e quinhentas de largura, em quadrado ao redor; terá cinquenta côvados ao redor para seus espaços abertos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 45, 3, 'E desta medida medirás o comprimento de vinte e cinco mil [côvados] ,e a largura de dez mil; e ali estará o santuário, [e] o lugar santíssimo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 45, 4, 'Este será o lugar santo da terra. Eles será para os sacerdotes que trabalham no santuário, que se achegam para servir ao SENHOR; e lhes servirá de lugar para casas, e de lugar santo para o santuário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 45, 5, 'E os levitas trabalhadores do templo terão como propriedade [uma área de] vinte e cinco mil [côvados] de comprimento, e dez mil de largura, com vinte câmaras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 45, 6, 'E [para] propriedade da cidade dareis cinco mil [canas] de largura e vinte e cinco mil de comprimento, em frente da oferta para o santuário; [esta] será para toda a casa de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 45, 7, 'E o príncipe terá [sua parte] de um lado e do outro da oferta ao santuário e da propriedade da cidade, diante da oferta para o santuário, e diante da propriedade da cidade, desde o canto ocidental para o ocidente, e desde o canto oriental para o oriente; e será o comprimento, em frente de uma das partes, desde o limite ocidental até o limite oriental.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 45, 8, 'Esta terra será sua propriedade em Israel, e meus príncipes nunca mais oprimirão a meu povo; ao invés disso entregarão a terra para a casa de Israel, conforme suas tribos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 45, 9, 'Assim diz o Senhor DEUS: Já basta, ó príncipes de Israel! Acabai a violência e a assolação; fazei juízo e justiça; tirai vossas imposições de meu povo, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 45, 10, 'Tereis balanças justas, efa justo, e bato justo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 45, 11, 'O efa e o bato serão de uma mesma medida; que o bato contenha a décima parte de um ômer, e o efa a décima parte de um ômer; a medida deles será conforme o ômer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 45, 12, 'E o siclo [será] de vinte geras: vinte siclos, mais vinte e cinco siclos, mais quinze siclos, vos serão uma mina.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 45, 13, 'Esta será a oferta que oferecereis: a sexta parte de um efa de ômer do trigo; também dareis a sexta parte de um efa de ômer da cevada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 45, 14, 'E quanto ao estatuto do azeite, [oferecereis] um bato de azeite, (o bato que é a décima parte de um coro, [que] é um ômer de dez batos; porque dez batos são um ômer).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 45, 15, 'E uma cordeira de cada duzentas do rebanho, da terra mais regada de Israel, para oferta de alimento, para holocausto e para oferta de gratidão, a fim de fazer expiação por eles, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 45, 16, 'Todo o povo desta terra terá que dar esta oferta para o príncipe de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 45, 17, 'E o príncipe terá que dar os holocaustos, as ofertas de alimento, e as ofertas de bebidas, nas solenidades, nas luas novas, nos sábados, e em todas as festas da casa de Israel; ele fará a expiação pelo pecado, a oferta de alimento, o holocausto, e as ofertas de gratidão, para fazer expiação pela casa de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 45, 18, 'Assim diz o Senhor DEUS: Ao primeiro [mês] , ao primeiro [dia] do mês, tomarás um bezerro sem defeito filho de vaca, e purificarás o santuário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 45, 19, 'E o sacerdote tomará do sangue do sacrifício pela expiação, e porá [dele] sobre os umbrais da casa, e sobre as quatro pontas da aresta do altar, e sobre os umbrais da porta do pátio interno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 45, 20, 'Assim também farás no sétimo [dia] do mês pelos que pecaram sem intenção ou por ignorância; assim expiarás a casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 45, 21, 'No primeiro [mês] , aos catorze dias do mês, tereis a páscoa, festa de sete dias; será comido pão sem fermento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 45, 22, 'E no mesmo dia o príncipe preparará por si e por todo o povo desta terra um bezerro de expiação pelo pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 45, 23, 'E nos sete dias da festa ele preparará um holocausto ao SENHOR: sete bezerros e sete carneiros sem defeito, cada dia dos sete dias; e um bode como expiação pelo pecado a cada dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 45, 24, 'Também preparará uma oferta de alimento: um efa para cada bezerro, e um efa para cada carneiro; e um him de azeite para cada efa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 45, 25, 'No sétimo [mês] , aos quinze dias do mês, na festa, ele fará o mesmo [todos] os sete dias, quanto ao sacrifício pela expiação, ao holocausto, à oferta de alimento, e ao azeite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 46, 1, 'Assim diz o Senhor DEUS: A porta do pátio de dentro que está voltada para oriente ficará fechada durante os seis dias de trabalho, porém no dia do sábado será aberta; também no dia de lua nova será aberta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 46, 2, 'E o príncipe entrará [pelo] caminho do pórtico da porta de fora, e estará em pé junto ao umbral da porta, enquanto os sacerdotes prepararão o seu holocausto e suas ofertas de gratidão; e ele ficará adorando junto ao umbral da porta, e depois sairá; porém a porta não será fechada até o anoitecer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 46, 3, 'E o povo da terra ficará prostrado diante do SENHOR junto à entrada da [mesma] porta, nos sábados e nas luas novas,.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 46, 4, 'E o holocausto que o príncipe oferecerá ao SENHOR no dia do sábado será seis cordeiros sem defeito e um carneiro sem defeito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 46, 5, 'E a oferta de alimento será um efa para cada carneiro; e para cada cordeiro um presente será o quanto ele puder dar, e um him de azeite para [cada] efa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 46, 6, 'Mas no dia da nova lua será um bezerro sem mancha, seis cordeiros, e um carneiro, que deverão ser sem defeito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 46, 7, 'E preparará [por] oferta de alimento um efa para o bezerro, e um efa para o carneiro; mas para os cordeiros, conforme o quanto puder; e um him de azeite para cada efa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 46, 8, 'E quando o príncipe entrar, ele entrará pelo caminho do pórtico da porta, e sairá pelo mesmo caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 46, 9, 'Mas quando o povo da terra vier para diante do SENHOR nas solenidades, aquele que entrar pelo caminho da porta do norte para adorar sairá pelo caminho da porta do sul; e aquele que entrar pelo caminho da porta do sul sairá pelo caminho da porta do norte; não voltará pelo caminho da porta por onde entrou, mas sairá pela [que estiver] à frente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 46, 10, 'E o príncipe entrará no meio deles quando eles entrarem, e quando eles saírem, sairão [juntos] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 46, 11, 'E nas festas e nas solenidades será a oferta de alimento um efa para cada bezerro, e um efa para cada carneiro; mas para os cordeiros, conforme o que ele puder dar; e um him de azeite para cada efa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 46, 12, 'E quando o príncipe fizer uma oferta voluntária de queima, ou ofertas de gratidão [como] oferta voluntária ao SENHOR, então lhe abrirão a porta que está voltada para o oriente; e ele fará seu holocausto e suas ofertas de gratidão assim como fizer no dia do sábado; depois sairá, e fecharão a porta depois dele sair.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 46, 13, 'E a cada dia prepararás um cordeiro sem defeito de um ano sem defeito como holocausto ao SENHOR; todas as manhãs o prepararás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 46, 14, 'E juntamente com ele todas as manhãs prepararás uma oferta de alimento, a sexta parte de um efa, e a terça parte de um him de azeite para misturar com a boa farinha; [será] uma oferta de alimento para o SENHOR, continuamente, por estatuto perpétuo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 46, 15, 'Assim prepararão o cordeiro e a oferta de alimento, todas as manhãs, em holocausto contínuo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 46, 16, 'Assim diz o Senhor DEUS: Quando o príncipe der de presente [algo] de sua herança a algum de seus filhos, isto pertencerá a seus filhos; será propriedade deles por herança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 46, 17, 'Porém se ele der de presente [algo] de sua herança a alguém de seus servos, pertencerá a ele até o ano da liberdade; então voltará ao príncipe, porque sua herança é de seus filhos; eles a herdarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 46, 18, 'E o príncipe não tomará nada da herança do povo, para os destituir da propriedade deles; de sua propriedade particular ele deixará de herança para seus filhos, para que meu povo não seja disperso, cada um de sua propriedade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 46, 19, 'Depois disto ele me trouxe pela entrada que estava ao lado da porta, às câmaras santas dos sacerdotes, as quais estavam voltadas para o norte; e havia ali um lugar no final, para o ocidente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 46, 20, 'E me disse: Este é o lugar onde os sacerdotes cozerão o sacrifício pela culpa e o pelo pecado; ali cozerão a oferta de alimento, para não [a] trazerem ao pátio de fora para santificar ao povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 46, 21, 'Então ele me levou ao pátio de fora, e me fez passar pelos quatro cantos do pátio; e eis que em cada canto do pátio havia outro pátio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 46, 22, 'Nos quatro cantos do pátio havia [outros] pátios fechados de quarenta côvados de comprimento, e trinta de largura; estes quatro cantos tinham uma mesma medida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 46, 23, 'E havia uma parede ao redor deles, ao redor dos quatro; e lugares de cozinhar abaixo ao redor das paredes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 46, 24, 'E me disse: Estas são as cozinhas, onde os trabalhadores da casa cozerão o sacrifício do povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 47, 1, 'Depois disto ele me fez voltar à entrada da casa; e eis que águas saíam de debaixo do umbral da casa para o oriente, pois a fachada da casa estava para o oriente; e as águas desciam de debaixo, desde o lado direito da casa, do lado sul do altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 47, 2, 'E ele me tirou [pelo] caminho da porta do norte, e me fez rodear pelo caminho de fora, até a porta externa, pelo caminho voltado ao oriente; e eis que águas corriam do lado direito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 47, 3, 'E quando aquele homem saiu para o oriente, tinha em sua mão um cordel de medir; ele mediu mil côvados, e me fez passar pelas águas, que [chegavam] aos tornozelos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 47, 4, 'E mediu mil [côvados] , e me fez passar pelas águas, que [chegavam] aos joelhos. Mediu [mais] mil, e me fez passar pelas águas, que [chegavam] à cintura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 47, 5, 'E mediu [mais] mil, e já era um rio que eu não podia passar, porque as águas eram tão profundas que o rio não se podia atravessar a pé, somente a nado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 47, 6, 'Então me disse: “Viste [isto] , filho do homem?” Depois ele me levou e trouxe-me de volta à margem do rio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 47, 7, 'Quando voltei, eis que na margem do rio havia muitíssimas árvores, de um lado e do outro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 47, 8, 'Então me disse: “Estas águas saem para a região do oriente, descem à planície, e entram no mar; e quando chegarem ao mar, tornarão saudáveis as águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 47, 9, 'E será que toda alma vivente que se move por onde quer que estes rio passar, viverá; e haverá muitíssimos peixes por ali terem passado estas águas, e ficarão saudáveis; e tudo viverá por onde quer que este este rio passar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 47, 10, 'Será também que pescadores estarão junto a ele; desde En-Gedi até En-Eglaim haverá [lugares para] se estender redes; seus peixes serão segundo suas espécies, como os peixes do grande mar, em muitíssima quantidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 47, 11, 'Porém seus charcos e seus pântanos não ficarão saudáveis; estarão salgados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 47, 12, 'E junto do rio, em suas margens de um lado e do outro, crescerá toda árvore de comer; sua folha nunca cairá, nem seu fruto faltará; em [todos os] seus meses produzirá frutos, porque suas águas saem do santuário; e seu fruto servirá de alimento, e sua folha de remédio.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 47, 13, 'Assim diz o Senhor DEUS: “Este é o limite em que tomareis a terra em herança segundo as doze tribos de Israel: José [terá] duas partes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 47, 14, 'E a herdareis igualmente, um como o outro; [terra] a qual jurei de mão levantada que daria aos vossos pais; portanto esta terra será a vossa herança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 47, 15, 'E este será o limite da terra para o lado norte: desde o mar Grande, a caminho de Hetlom, e indo por Lebo-Hamate até Zedade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 47, 16, 'Berota, Sibraim (que está entre o limite de Damasco e o limite de Hamate); Hazer-Haticom, que está junto ao limite de Haurã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 47, 17, 'E o limite será do mar [até] Haser-Enom, ao limite de Damasco ao norte, e ao limite de Hamate; [este será] o lado norte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 47, 18, 'Ao lado do oriente, passando entre Haurã e Damasco, e entre Gileade e a terra de Israel, junto ao Jordão; medireis desde o limite até do mar do oriente; [este será] o lado do oriente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 47, 19, 'E ao lado sul, ao sul, será desde Tamar até as águas de Meribá-Cades, indo ao longo do ribeiro até o grande mar; e [este será] o lado sul, ao sul.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 47, 20, 'E o lado do ocidente será o grande mar, desde o limite até Lebo-Hamate; este será o lado do ocidente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 47, 21, 'Repartireis, pois, esta terra entre vós, segundo as tribos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 47, 22, 'E será que a sorteareis em herança para vós, e para os estrangeiros que peregrinam entre vós, que tiverem gerado filhos entre vós; e vos serão como nativos entre os filhos de Israel; repartirão herança convosco, entre as tribos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 47, 23, 'E será que na tribo onde o estrangeiro peregrinar, ali [lhe] dareis sua herança”, diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 1, 'E estes são os nomes das tribos: Desde o extremo norte, do lado do caminho de Hetlom, vindo para Hamate, Hazar-Enom, ao limite de Damasco, para o norte, ao lado de Hamate; sendo seus extremos do oriente e do ocidente: esta é a porção de Dã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 2, 'Junto ao limite de Dã, desde o extremo oriente até o extremo ocidente: esta é a porção de Aser.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 3, 'Junto ao limite de Aser, desde o extremo oriente até o extremo ocidente: esta é a porção de Naftali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 4, 'Junto ao limite de Naftali, desde o extremo oriente até o extremo ocidente: esta é a porção de Manassés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 5, 'Junto ao limite de Manassés, desde o extremo oriente até o extremo ocidente: esta é a porção de Efraim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 6, 'Junto ao limite de Efraim, desde o extremo oriente até o extremo ocidente: esta é a porção de Rúben.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 7, 'Junto ao limite de Rúben, desde o extremo oriente até o extremo ocidente: esta é a porção de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 8, 'E junto ao limite de Judá, desde o lado do oriente até o lado do ocidente, será a oferta que reservareis, de vinte e cinco mil [canas] de largura, e de comprimento, como uma das [demais] partes, desde o lado do oriente até o lado do ocidente; e o santuário estará no meio dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 9, 'A oferta que reservareis ao SENHOR será de vinte e cinco mil [canas] de comprimento e dez mil de largura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 10, 'E ali será a oferta santa dos sacerdotes, de vinte e cinco mil [canas] ao norte, dez mil de largura ao ocidente, dez mil de largura ao oriente, e de vinte e cinco mil de comprimento ao sul; e o santuário do SENHOR estará no meio dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 11, 'Será para os sacerdotes santificados dos filhos de Zadoque, que guardaram minha ordem, que não se desviaram quando os filhos de Israel se desviaram, como se desviaram os [outros] levitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 12, 'Eles terão uma oferta da oferta da terra, a parte santíssima, junto ao limite dos levitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 13, 'E o Levitas terão na vizinhança do limite dos sacerdotes vinte e cinco mil [canas] de comprimento e de dez mil de largura; todo o comprimento será vinte e cinco mil, e a largura dez mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 14, 'Não venderão disto, nem trocarão, nem transferirão as primícias da terra, pois é coisa consagrada ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 15, 'E as cinco mil [canas] de largura que restam das vinte e cinco mil, serão de uso comum para a cidade, para habitação e arredores; e a cidade estará no meio delas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 16, 'E estas serão suas medidas: o lado norte quatro mil e quinhentas [canas] , o lado sul quatro mil e quinhentas, o lado do oriente quatro mil e quinhentas, e o lado do ocidente quatro mil e quinhentas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 17, 'E o arrebaldes da cidade serão ao norte de duzentas e cinquenta [canas] , ao sul de duzentas e cinquenta, ao oriente de duzentas e cinquenta, e ao ocidente de duzentas e cinquenta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 18, 'E quanto ao que restar do comprimento, na vizinhança da oferta santa, será dez mil [canas] ao oriente e dez mil ao ocidente, que será vizinho à oferta santa; sua produção será alimento dos trabalhadores da cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 19, 'E os trabalhadores da cidade, de todas as tribos de Israel, trabalharão nela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 20, 'Toda a oferta será de vinte e cinco mil [canas] por vinte e cinco mil, em quadrado; reservareis a oferta santa, com a propriedade da cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 21, 'E o que restar será para o príncipe, de um lado e do outro da oferta santa, e da propriedade da cidade, desde a distância de vinte e cinco mil [canas] da oferta, até o extremo oriente, e ao ocidente desde a distância de vinte e cinco mil [canas] da oferta até o extremo ocidente, na vizinhança das porções [das tribos] , será para o príncipe; e a oferta santa, e o santuário da casa será no meio dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 22, 'E desde a propriedade dos Levitas, e desde a propriedade da cidade, [será] no meio daquilo que pertencerá ao príncipe. Entre o limite de Judá e o limite de Benjamim será para o príncipe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 23, 'E quanto às demais tribos: desde o extremo oriente até o extremo ocidente: esta é a porção de Benjamim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 24, 'E junto ao limite de Benjamim, desde o extremo oriente até o extremo ocidente: esta é a porção de Simeão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 25, 'E junto ao limite de Simeão, desde o extremo oriente até o extremo ocidente: esta é a porção de Issacar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 26, 'E junto ao limite de Issacar, desde o extremo oriente até o extremo ocidente: esta é a porção de Zebulom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 27, 'E junto ao limite de Zebulom, desde o extremo oriente até o extremo ocidente: esta é a porção de Gade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 28, 'E junto ao limite de Gade, ao sul, no lado sul, será o limite desde Tamar até as águas das inimizades de Cades, junto ao ribeiro, até o grande mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 29, 'Esta é a terra que repartireis em herança às tribos de Israel, e estas são suas porções,diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 30, 'E estas são as saídas da cidade: ao lado norte quatro mil e quinhentos [côvados] de medida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 31, 'E as portas da cidade serão conforme os nomes das tribos de Israel; três portas ao norte: uma porta de Rúben, uma porta de Judá, [e] uma porta de Levi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 32, 'E ao lado do oriente quatro mil e quinhentos [côvados] , e três portas: uma porta de José, uma porta de Benjamim, [e] uma porta de Dã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 33, 'E ao lado sul quatro mil e quinhentos [côvados] de medida, e três portas: uma porta de Simeão, uma porta de Issacar, [e] uma porta de Zebulom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 34, 'E ao lado do ocidente quatro mil e quinhentos [côvados] ,[e] suas três portas: uma porta de Gade, uma porta de Aser, [e] uma porta de Naftali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 48, 35, 'Ao redor terá dezoito mil [côvados] . E o nome da cidade desde [aquele] dia será: O SENHOR Está Ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 1, 1, 'No ano terceiro do reinado de Jeoaquim, rei de Judá, Nabucodonosor, rei da Babilônia, veio a Jerusalém, e a cercou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 1, 2, 'E o Senhor entregou em suas mãos a Jeoaquim, rei de Judá, e uma parte dos vasos da casa de Deus, e os trouxe à terra de Sinar, para a casa de seu deus; e pôs os vasos na casa do tesouro de seu deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 1, 3, 'E o rei disse a Aspenaz, chefe de seus eunucos, que trouxesse [alguns] dos filhos de Israel, da família real, e dos príncipes,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 1, 4, 'Rapazes em quem não houvesse defeito físico algum, de boa aparência, entendidos em toda sabedoria, sábios em conhecimento, de boa inteligência, e que tivessem habilidade em prestar assistência no palácio do rei; e que os ensinassem as letras e a língua dos caldeus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 1, 5, 'E o rei lhes determinou uma porção diária de alimento, da comida do rei, e do vinho que bebia; e que [assim] fossem tratados por três anos, para que ao fim eles estivessem diante do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 1, 6, 'E foram entre eles, dos filhos de Judá, Daniel, Ananias, Misael e Azarias,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 1, 7, 'Aos quais o chefe dos eunucos pôs [outros] nomes: a Daniel, Beltessazar; a Ananias, Sadraque; a Misael, Mesaque; e a Azarias, Abednego.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 1, 8, 'E Daniel propôs em seu coração de não se contaminar com a porção diária de alimento da comida do rei, nem no vinho que ele bebia; então pediu ao chefe dos eunucos para não se contaminar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 1, 9, '(Pois Deus concedeu a Daniel o agrado e o favor do chefe dos eunucos.)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 1, 10, 'E disse o chefe dos eunucos a Daniel: Tenho medo de meu senhor o rei, que determinou vossa comida e vossa bebida; pois, e se ele perceber que vossos rostos estão com pior aparência que os dos rapazes que são semelhantes a vós? Assim poríeis minha cabeça em risco diante do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 1, 11, 'Então disse Daniel a Melsar, a quem o chefe dos eunucos havia ordenado sobre Daniel, Ananias, Misael, e Azarias:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 1, 12, 'Faze um teste, eu te peço, com teus servos por dez dias, e dê-nos legumes para comer, e água para beber.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 1, 13, 'Então se vejam diante de ti nossos rostos, e os rostos dos rapazes que comem da porção de alimento da comida do rei; e faze com teus servos conforme o que vires.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 1, 14, 'E ele consentiu-lhes nisto, e fez teste com eles por dez dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 1, 15, 'E ao fim dos dez dias foi visto que eles estavam com rostos de melhor aparência e mais bem nutridos que os outros rapazes que comiam da porção de alimento do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 1, 16, 'Foi assim que Melsar lhes tirou a porção de alimento deles, e o vinho que deviam beber, e continuou a lhes dar legumes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 1, 17, 'Quanto a estes quatro rapazes, Deus lhes deu conhecimento e inteligência em todas as letras e sabedoria; Daniel, porém, teve entendimento em toda visão e sonhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 1, 18, 'E quando terminaram os dias dos quais o rei tinha dito que os trouxessem, o chefe dos eunucos os trouxe diante de Nabucodonosor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 1, 19, 'E o rei falou com eles, e entre todos eles não foi achado [alguém] como Daniel, Ananias, Misael, e Azarias; e assim se tornaram assistentes diante do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 1, 20, 'E em todo negócio de sabedoria [e] inteligência que o rei lhes demandou, achou-os dez vezes melhores que todos os magos e astrólogos que havia em todo o seu reino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 1, 21, 'E Daniel esteve até o primeiro ano do rei Ciro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 1, 'E no segundo ano do reinado de Nabucodonosor, sonhou Nabucodonosor sonhos, e seu espírito se perturbou, de modo que perdeu o sono.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 2, 'E o rei mandou chamar magos, astrólogos, encantadores, e sábios dos caldeus, para que explicassem ao rei seus sonhos. Eles vieram, e se apresentaram diante do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 3, 'E o rei lhes disse: Sonhei um sonho, e meu espírito está perturbado para saber o sonho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 4, 'Então os caldeus falaram ao rei em língua aramaica: Ó rei, vive para sempre vive! Dize o sonho a teus servos, e mostraremos a interpretação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 5, 'Então o rei respondeu aos caldeus, e disse: Minha decisão é firme: se não me mostrardes o sonho e sua interpretação, sereis despedaçados, e vossas casas se tornarão em monturos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 6, 'Mas se mostrardes o sonho e sua interpretação, recebereis de mim presentes, recompensas e grande honra; portanto, mostrai-me o sonho e sua interpretação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 7, 'Responderam pela segunda vez, e disseram: Diga o rei o sonho a seus servos, e mostraremos sua interpretação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 8, 'O rei respondeu, e disse: Eu bem sei que vós quereis ganhar tempo; porque sabeis que minha decisão é firme.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 9, 'Pois se não me mostrardes o sonho, haverá uma única sentença para vós. Pois preparastes uma resposta mentirosa e perversa para dizer diante de mim, até que o tempo se mude; portanto, dizei-me o sonho, para que eu tenha certeza de que podeis me mostrar sua interpretação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 10, 'Os caldeus responderam diante do rei, e disseram: Ninguém há sobre a terra que possa mostrar a palavra do rei; pois nenhum rei, príncipe, nem governante, jamais exigiu coisa semelhante a algum mago, astrólogo, ou caldeu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 11, 'Pois a coisa que o rei exige é tão difícil que não há quem a possa revelar diante do rei, a não ser os deuses, cuja morada não é entre a raça humana.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 12, 'Por isso o rei se irou muito e se enfureceu; então mandou matar a todos os sábios da Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 13, 'E publicou-se o decreto, e os sábios foram condenados à morte; e buscaram a Daniel e a seus companheiros para serem mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 14, 'Então Daniel falou de forma cautelosa e prudente a Arioque, capitão dos da guarda do rei, que tinha saído para matar os sábios de Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 15, 'Ele respondeu e disse a Arioque, capitão do rei: Por que houve este mandamento do rei tão repentinamente? Então Arioque explicou o ocorrido a Daniel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 16, 'E Daniel entrou, e pediu ao rei que lhe desse tempo para que ele mostrasse a interpretação ao rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 17, 'Então Daniel foi para sua casa, e contou o ocorrido a Ananias, Misael, e Azarias, seus companheiros,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 18, 'Para que pedissem misericórdia do Deus do céu sobre este mistério, e que Daniel e seus companheiros não perecessem juntamente com os demais sábios da Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 19, 'Então o mistério foi revelado a Daniel em visão de noite; então Daniel louvou ao Deus do céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 20, 'Daniel falou, e disse: Bendito seja o nome de Deus para todo o sempre! Porque a ele pertence a sabedoria e o poder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 21, 'E ele é o que muda os tempos e as estações; ele tira os reis, e confirma os reis; ele é o que dá a sabedoria aos sábios, e a conhecimento aos entendidos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 22, 'Ele revela o profundo e o escondido; conhece o que está nas trevas, e a luz mora com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 23, 'A ti, ó Deus de meus pais, te agradeço e louvo, pois tu me deste sabedoria e poder, e agora me fizeste saber o que te pedimos; porque tu nos fizeste saber o assunto do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 24, 'Depois disto Daniel veio a Arioque, ao qual o rei tinha constituído para matar os sábios da Babilônia; ele veio, e disse-lhe assim: Não mates os sábios da Babilônia; leva-me diante do rei, que eu mostrarei ao rei a interpretação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 25, 'Então Arioque levou depressa a Daniel diante do rei, e disse-lhe assim: Achei um homem dos do cativos de Judá, o qual mostrará ao rei a interpretação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 26, 'Respondeu o rei, e disse a Daniel (cujo nome era Beltessazar): Podes tu me explicar o sonho que vi, e sua interpretação?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 27, 'Daniel respondeu diante do rei, e disse: O mistério que o rei demanda, nem sábios, nem astrólogos, nem magos, nem adivinhos podem explicar ao rei;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 28, 'Mas há um Deus nos céus, o qual revela os mistérios; ele, pois, fez saber ao rei Nabucodonosor o que haverá de acontecer no fim dos dias. Teu sonho, e as visões de tua cabeça sobre tua cama, são o seguinte:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 29, 'Enquanto tu, ó rei, estava em tua cama, vieram teus pensamentos saber o irá acontecer no futuro; pois aquele que revela os mistérios te mostrou o que haverá de acontecer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 30, 'E a mim foi revelado este mistério, não porque em mim há mais sabedoria que em todos os viventes, mas sim para que eu explique a interpretação ao rei, e assim entendas os pensamentos de teu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 31, 'Tu, ó rei, estavas vendo, e eis uma grande estátua. Esta estátua, que era muito grande, e tinha um esplendor excelente, estava em pé diante de ti; e sua aparência era terrível.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 32, 'A cabeça da estátua era de ouro puro; seus peito e seus braços, de prata; seu ventre e suas coxas, de bronze;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 33, 'Suas pernas de ferro; seus pés, em parte de ferro, e em parte de barro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 34, 'Estavas tu vendo, até que uma pedra foi cortada sem [auxílio de] mãos, a qual feriu a estátua em seus pés de ferro e de barro, e os esmigalhou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 35, 'Então foi juntamente esmigalhado o ferro, o barro, o bronze, a prata e o ouro, e se tornaram como o pó das eiras de verão; e o vento os levou, e nunca se achou algum lugar para eles. Mas a pedra que feriu a estátua, se tornou um grande monte, que encheu toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 36, 'Este é o sonho; a interpretação dele também diremos diante do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 37, 'Tu, ó rei, és rei de reis; pois o Deus do céu te deu o reino, poder, força, e majestade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 38, 'E onde quer que habitam filhos de homens, animais do campo, e aves do céu, ele os entregou em tuas mãos, e fez com que tivesses domínio sobre tudo; tu és a cabeça de ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 39, 'E depois de ti se levantará outro reino inferior ao; e outro terceiro reino de bronze, o qual dominará toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 40, 'E o quarto reino será forte como o ferro; e tal como o ferro esmigalha e despedaça tudo, e tal como o ferro que quebra todas estas coisas, assim também ele esmigalhará e quebrará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 41, 'E o que viste dos pés e dos dedos, em parte de barro de oleiro, e em parte de ferro, isso será um o reino dividido; mas haverá nele [algo] da força do ferro, conforme o que viste o ferro misturado com o barro mole.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 42, 'E os dedos dos pés em parte de ferro, e em parte de barro, são que em parte o reino será forte, e em parte será frágil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 43, 'Quanto ao que viste, o ferro misturado com barro mole, misturar-se-ão com semente humana, mas não se ligarão um ao outro, como o ferro não se mistura com o barro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 44, 'Mas nos dias destes reis, o Deus do céu levantará um reino que nunca será destruído; e este reino não será deixado para outro povo; ao contrário, esmigalhará e consumirá todos estes reinos, e [tal reino] permanecerá para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 45, 'Por isso viste que do monte foi cortada uma pedra sem [auxílio de] mãos, a qual esmigalhou o ferro, o bronze, o barro, a prata, e o ouro. O grande Deus mostrou ao rei o que irá acontecer no futuro. O sonho é verdadeiro, e sua interpretação é fiel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 46, 'Então o rei Nabucodonosor caiu com o rosto ao chão, prostrou-se diante de Daniel, e mandou que lhe sacrificassem oferta de alimento e incensos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 47, 'O rei respondeu a Daniel, e disse: Certamente vosso Deus é o Deus dos deuses, o Senhor dos reis, e o revelador dos mistérios, pois pudeste revelar este mistério.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 48, 'Então o rei engrandeceu a Daniel, e lhe deu muitos e grandes presentes, e o pôs por governador de toda a província da Babilônia, e por príncipe dos governadores sobre todos os sábios de Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 2, 49, 'E Daniel pediu do rei, e ele pôs sobre os negócios da província de Babilônia a Sadraque, Mesaque, e Abednego; porém Daniel [ficou] na corte do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 1, 'O rei Nabucodonosor fez uma estátua de ouro, cuja altura era de sessenta côvados, sua largura de seis côvados; ergueu-a no campo de Dura, na província da Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 2, 'E o rei Nabucodonosor mandou juntar os sátrapas, os prefeitos e governadores, os juízes, tesoureiros, conselheiros, os oficiais, e a todos os líderes das províncias, para que viessem à consagração da estátua que o rei Nabucodonosor havia erguido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 3, 'Então se reuniram os sátrapas, os prefeitos e governadores, os juízes, tesoureiros, conselheiros, os oficiais, e todos os líderes das províncias, para a consagração da estátua que o rei Nabucodonosor havia erguido; e estavam em pé diante da estátua que Nabucodonosor havia erguido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 4, 'E o arauto proclamava em alta voz: Manda-se a vós, ó povos, nações, e línguas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 5, 'Que quando ouvirdes o som da trombeta, do pífano, da cítara, da harpa, do saltério, da flauta, e de todo instrumento musical, vos prostrareis e adorareis a estátua de ouro que o rei Nabucodonosor ergueu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 6, 'E qualquer um que não se prostrar e [a] adorar, na mesma hora será lançado dentro de uma fornalha de fogo ardente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 7, 'Por isso no mesmo instante em todos os povos ouviram o som da trombeta, do pífano, da cítara, da harpa, do saltério, da flauta, e de todo instrumento musical, todos os povos, nações, e línguas se prostraram, e adoraram a estátua de ouro que o rei Nabucodonosor havia erguido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 8, 'Por isso no mesmo instante [alguns] homens caldeus se chegaram, e acusaram dos judeus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 9, 'Eles falaram ao rei Nabucodonosor: Ó rei, vive para sempre!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 10, 'Tu, ó rei, fizeste um decreto que todo aquele que ouvisse o som da trombeta, do pífano, do da cítara, da harpa, do saltério, da flauta, e de todo instrumento musical, se prostrasse e adorasse a estátua de ouro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 11, 'E qualquer um que não se prostrasse e adorasse, fosse lançado dentro de uma fornalha de fogo ardente'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 12, 'Há uns homens judeus, os quais constituíste sobre os negócios da província da Babilônia; Sadraque, Mesaque, e Abednego; estes homens, ó rei, não te respeitaram; não servem a teus deuses, nem adoram a estátua de ouro que tu ergueste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 13, 'Então Nabucodonosor com ira e furor, mandou trazer a Sadraque, Mesaque, e Abednego. Então trouxeram estes homens diante do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 14, 'Nabucodonosor lhes disse: É verdade, Sadraque, Mesaque, e Abednego, que vós não servis a meus deuses, nem adorais a estátua de ouro que ergui?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 15, 'Agora pois, se estais prontos, quando ouvirdes o som da trombeta, do pífano, da cítara, da harpa, do saltério, da flauta, e de todo instrumento musical, prostrai-vos e adorai a estátua que eu fiz. Porém se não a adorardes, na mesma hora sereis lançados dentro da fornalha de fogo ardente; e quem é o Deus que vos livrará de minhas mãos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 16, 'Sadraque, Mesaque, e Abednego responderam ao rei Nabucodonosor: Não necessitamos de responder sobre este negócio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 17, 'Eis que nosso Deus a quem servimos pode nos livrar da fornalha de fogo ardente; e ele nos livrará de tua mão, ó rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 18, 'E se não, sabe tu, ó rei, que não serviremos a teus deuses, nem adoraremos a estátua que ergueste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 19, 'Então Nabucodonosor se encheu de furor, e o aspecto de seu rosto se mudou contra Sadraque, Mesaque, e Abednego. Então ele falou, e mandou que o forno fosse aceso sete vezes mais do que costumava se acender.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 20, 'E mandou aos homens mais fortes que havia em seu exército, que atassem a Sadraque, Mesaque, e Abednego, para lançá-los na fornalha de fogo ardente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 21, 'Então estes homens foram atados com suas capas, suas calças, seus turbantes, e suas vestes, e foram lançados dentro da fornalha de fogo ardente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 22, 'E visto que a palavra do rei era urgente, e a fornalha estava muitíssimo quente, a chama do fogo matou aqueles homens que tinham levantado a Sadraque, Mesaque, e Abednego.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 23, 'E estes três homens, Sadraque, Mesaque, e Abednego, caíram atados dentro da fornalha de fogo ardente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 24, 'Então o rei Nabucodonosor se espantou, e se levantou depressa, então perguntou aos seus conselheiros: Não lançamos três homens atados dentro do fogo? Eles responderam ao rei: É verdade, ó rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 25, 'Ele disse mais: Eis que vejo quatro homens soltos andando no meio do fogo, e não há neles dano algum; e a aparência do quarto é semelhante a um filho de deuses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 26, 'Então Nabucodonosor se aproximou da porta da fornalha de fogo ardente, e falou: Sadraque, Mesaque, e Abednego, servos do Deus altíssimo, saí e vinde!Então Sadraque, Mesaque, e Abednego saíram do meio do fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 27, 'E juntaram-se os sátrapas, os prefeitos, os governadores, e os conselheiros do rei, para olharem estes homens, como o fogo não havia causado efeito algum em seus corpos, nem o cabelo de seus cabeças fora queimado, nem suas capas se mudaram, nem cheiro de fogo passara por eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 28, 'Nabucodonosor falou: Bendito seja o Deus de Sadraque, Mesaque, e Abednego, que enviou seu anjo, e livrou seus servos, que confiaram nele; pois violaram o mandamento do rei, e entregaram seus corpos para que servissem nem adorassem [algum] outro deus, a não ser o seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 29, 'Portanto eu faço um decreto, que todo povo, nação, e língua, que disser blasfêmia contra o Deus de Sadraque, Mesaque, e Abednego, seja despedaçado, e sua casa seja se torne um amontoado de entulhos; pois não há outro deus que possa livrar como este.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 3, 30, 'Então o rei fez com que Sadraque, Mesaque, e Abednego fossem prósperos na província da Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 1, 'O rei Nabucodonosor, a todos os povos, nações, e línguas, que moram em toda a terra: paz vos seja multiplicada;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 2, 'Pareceu-me bem fazer conhecidos os sinais e maravilhas que o Deus altíssimo fez comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 3, 'Como são grandes os seus sinais, e como são poderosas as suas maravilhas! O reino dele é um reino eterno, e seu domínio de geração em geração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 4, 'Eu, Nabucodonosor, estava tranquilo em minha casa, e próspero em meu palácio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 5, 'Eu vi um sonho que me espantou; e as imaginações em minha cama e as visões da minha cabeça me perturbaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 6, 'Por isso eu fiz um decreto para que trouxessem diante de mim todos os sábios da Babilônia, para que me fizessem saber a interpretação do sonho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 7, 'Então vieram magos, astrólogos, caldeus, e adivinhos; e eu disse o sonho diante deles, mas não conseguiram me mostrar sua interpretação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 8, 'Porém por fim veio diante de mim Daniel, cujo nome é Beltessazar, segundo o nome de meu deus; e em [Daniel] há o espírito dos deuses santos. Então eu disse o sonho diante dele:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 9, 'Beltessazar, príncipe dos magos, de quem eu sei que há em ti espírito dos deuses santos, e que nenhum mistério é difícil para ti, dize-me as visões de meu sonho que eu vi, e sua interpretação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 10, 'Estas foram as visões de minha cabeça em minha cama: eu estava vendo, e eis uma árvore grande em altura, no meio da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 11, 'Esta árvore crescia, e se fortalecia; sua altura chegava até o céu, e podia ser vista até dos confins de toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 12, 'Sua folhagem era bela, seu fruto abundante, e havia nela alimento para todos. Debaixo dela os animais do campo achavam sombra, em seus ramos as aves do céu faziam morada, e todos os seres se alimentavam dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 13, 'Eu estava vendo nas visões de minha cabeça em minha cama, e eis que um vigilante e santo descia do céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 14, 'Ele gritava fortemente e dizia assim: Cortai a árvore, e podai seus ramos; derrubai sua folhagem, e dispersai seu fruto; fujam os animais debaixo dela, e as aves de seus ramos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 15, 'Porém deixai o tronco [com] suas raízes na terra, e com correntes de ferro e de bronze na erva do campo; e seja molhado com o orvalho do céu, e sua parte seja com os animais na grama da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 16, 'Seu coração seja mudado, para que não seja coração de homem, e seja-lhe dado um coração de animal; e passem sobre ele sete tempos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 17, 'Esta sentença é por decreto dos vigilantes, esta exigência pela palavra dos santos; para que os viventes saibam que o Altíssimo tem o domínio dos reinos humanos, e ele os dá a quem ele quer, e constitui sobre eles até o mais inferior dos seres humanos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 18, 'Este foi o sonho que eu, o rei Nabucodonosor, vi. Tu, pois, Beltessazar, dize a interpretação, porque todos os sábios do meu reino não puderam me revelar sua interpretação; mas tu podes, porque há em ti o espírito dos deuses santos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 19, 'Então Daniel, cujo nome era Beltessazar, ficou atônito por um certo tempo, e seus pensamentos o espantavam. O rei falou: Beltessazar, não fiques espantado com o sonho nem com sua interpretação. Beltessazar respondeu: Meu senhor, que o sonho seja para os que te odeiam, e sua interpretação para teus inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 20, 'A árvore que viste, que crescera e se fizera forte, cuja altura chegava até o céu, e podia ser vista por toda a terra,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 21, 'Cuja folhagem era formosa, seu fruto abundante, e em que havia alimento para todos; debaixo da qual moravam os animais do campo, e em seus ramos habitavam as aves do céu,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 22, 'Ela és tu, ó rei, que cresceste, e te fizeste forte; pois tua grandeza cresceu, e chegou até o céu; e teu domínio até o fim da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 23, 'E quanto ao que o rei viu, um vigilante e santo que descia do céu, e dizia: Cortai a árvore e destruí-a; mas o tronco [com] suas raízes deixai na terra, com correntes de ferro e de bronze na erva do campo; e seja molhado do orvalho do céu, e sua parte seja com os animais do campo, até que passem sobre ele sete tempos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 24, 'Esta é a interpretação, ó rei; esta é a sentença do Altíssimo, que virá sobre o rei, meu senhor:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 25, 'Expulsar-te-ão dentre os homens, e tua morada será com os animais do campo; serás alimentado com erva como aos bois, e serás molhado com orvalho do céu; e sete tempos passarão sobre ti, até que entendas que o Altíssimo tem o domínio sobre os reinos humanos, e ele os dá a quem ele quer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 26, 'E quanto ao que foi dito, que deixassem o tronco [com] das raízes da árvore, significa que teu reino se te será restabelecido, depois que tiveres entendido que o céu reina.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 27, 'Portanto, ó rei, aceita meu conselho, e desfaze teus pecados por meio da justiça, e tuas maldades por meio da misericórdia para com os pobres; para que talvez haja uma prolongamento de tua paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 28, 'Tudo isso veio sobre o rei Nabucodonosor;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 29, '[Pois] ao fim de doze meses, enquanto passeava sobre o palácio real da Babilônia,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 30, 'O rei falou: Não é esta a grande Babilônia, que eu edifiquei para ser a capital do reino, com a força de meu poder, e para a glória de minha majestade?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 31, 'Enquanto a palavra ainda estava na boca do rei, uma voz caiu do céu: A ti se diz, ó rei Nabucodonosor: perdeste o teu reino,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 32, 'E te expulsarão dentre os homens. Tua morada será com os animais do campo, e com erva serás alimentado, como os bois; e sete tempos passarão sobre ti, até que entendas que o Altíssimo tem o domínio dos reinos dos homens, e ele os dá a quem ele quer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 33, 'Na mesma hora a palavra se cumpriu sobre Nabucodonosor, e foi lançado dentre os homens. Ele passou a comer erva como os bois, e seu corpo foi molhado com o orvalho do céu, até que seu pelo cresceu como [as penas] da águia, e suas unhas como [as garras] das aves.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 34, 'Mas ao fim daqueles dias, eu, Nabucodonosor levantei meus olhos ao céu, e meu entendimento voltou a mim; então eu bendisse ao Altíssimo, e louvei e glorifiquei ao que vive para sempre, cujo domínio é eterno, e seu reino de geração em geração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 35, 'E todos os moradores da terra são contados como nada; e ele faz no exército do céu, e nos habitantes da terra segundo sua vontade; ninguém há que possa deter sua mão, e lhe dizer: Que fazes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 36, 'No mesmo tempo meu entendimento voltou a mim, e a dignidade do meu reino, minha majestade e meu resplendor voltaram a mim; e meus conselheiros e meus grandes me buscaram; e eu fui restabelecido em meu reino, e maior glória me foi acrescentada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 4, 37, 'Agora eu, Nabucodonosor louvo, exalto e glorifico ao Rei do céu, porque todas as suas obras são verdade, e seus caminhos juízo; e ele pode humilhar aos que andam com arrogância.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 1, 'O rei Belsazar fez um grande banquete a mil de seus maiorais, e bebeu vinho diante destes mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 2, 'Tendo Belsazar experimentado o vinho, mandou trazer os vasos de ouro e de prata que seu pai Nabucodonosor tirara do templo de Jerusalém, para que bebessem com eles o rei e seus maiorais, suas mulheres e suas concubinas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 3, 'Então trouxeram os vasos de ouro que foram tirados do templo da casa de Deus, que estava em Jerusalém; e beberam com eles o rei e seus maiorais, suas mulheres e suas concubinas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 4, 'Beberam vinho, e louvaram aos deuses de ouro e de prata, de bronze, de ferro, de madeira, e de pedra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 5, 'Naquela mesma hora saíram dedos de uma mão de homem, e escreveram diante do castiçal na caiadura da parede do palácio real, e o rei viu parte da mão que estava escrevendo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 6, 'Então o semblante do rei se mudou, e seus pensamentos o perturbaram; as juntas de seus lombos se desataram, e seus joelhos se bateram um com o outro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 7, 'O rei clamou em alta voz que trouxessem astrólogos, caldeus, e adivinhos. O rei falou, e disse aos sábios da Babilônia: Qualquer um que ler esta escritura, e me mostrar sua interpretação, será vestido de púrpura, terá uma corrente de ouro a seu pescoço, e será o terceiro líder no reino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 8, 'Então vieram todos os sábios do rei, mas não puderam ler a escritura, nem fazer saber ao rei sua interpretação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 9, 'Então o rei Belsazar ficou muito perturbado, e se mudou seu semblante; seus maiorais estavam perturbados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 10, 'A rainha, por causa das palavras do rei e de seus maiorais, entrou na casa do banquete. A rainha disse: Ó rei, vive para sempre! Não te perturbem teus pensamentos, nem se mude teu semblante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 11, 'Em teu reino há um homem no qual mora o espírito dos deuses santos; e nos dias de teu pai se achou nele luz, inteligência e sabedoria, como a sabedoria dos deuses; e teu pai, o rei Nabucodonosor (o rei, teu pai), o constituiu por príncipe sobre os magos, os astrólogos, os caldeus e os adivinhadores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 12, 'Pois nele foi achado um espírito extraordinário, conhecimento, e entendimento, interpretando sonhos, resolvendo enigmas, e desfazendo dúvidas. Ele é Daniel, a quem o rei pôs por nome Beltessazar. Chame-se agora a Daniel, e ele mostrará a interpretação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 13, 'Então Daniel foi trazido diante do rei. E o rei disse a Daniel: És tu aquele Daniel dos cativos de Judá, que meu pai trouxe de Judá?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 14, 'Pois tenho ouvido de ti que o espírito dos deuses está em ti, e que em ti se acha luz, entendimento e extraordinária sabedoria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 15, 'E agora foram trazidos diante de mim sábios e astrólogos, para que lessem esta escritura, e me fizessem saber sua interpretação; mas eles não puderam mostrar a interpretação destas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 16, 'Eu, porém, tenho ouvido sobre ti que podes dar interpretações, e solucionar dúvidas. Agora, se puderes puderes ler esta escritura, e fazer-me saber sua interpretação, serás vestido de púrpura, corrente de ouro terás em teu pescoço, e serás o terceiro líder no reino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 17, 'Então Daniel respondeu, e disse diante do rei: Fiquem contigo tuas dádivas, e dá teus presentes a outro; contudo lerei a escritura ao rei, e lhe farei saber a interpretação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 18, 'Quanto a ti, ó rei, o Deus Altíssimo deu a teu pai Nabucodonosor o reino, a grandeza, a glória, e a majestade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 19, 'E pela grandeza que ele lhe deu, todos os povos, nações, e línguas tremiam e temiam diante dele. Ele matava a quem queria, e concedia vida a quem queria; ele engrandecia a quem queria, e abatia a quem queria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 20, 'Mas quando seu coração se exaltou, e seu espírito se endureceu em soberba, ele foi deposto do trono de seu reino, e a glória lhe foi tirada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 21, 'E foi expulso dentre os filhos dos homens; e sua mente se tornou semelhante à dos animais, e com asnos selvagens foi sua morada. Foi alimentado com erva tal como os bois, e seu corpo foi molhado com o orvalho do céu, até que entendeu que o Deus altíssimo tem o domínio sobre os reinos humanos, e constitui sobre eles a quem ele quer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 22, 'E tu, Belsazar, filho dele, não humilhaste teu coração, mesmo sabendo de tudo isto;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 23, 'Em vez disso exaltaste a ti mesmo contra o Senhor do céu; pois trouxeram diante de ti os vasos de sua casa, e tu, teus maiorais, tuas mulheres e tuas concubinas, bebestes vinho neles; além disto, louvaste a deuses de prata, ouro, bronze, de ferro, madeira e pedra, que não veem, nem ouvem, nem têm conhecimento algum; porém ao Deus em cuja mão está tua vida e todos os teus caminhos, a ele não glorificaste;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 24, 'Então dele foi enviada aquela parte da mão que esculpiu esta escritura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 25, 'E esta é a escritura que foi escrita: MENE, MENE, TEQUEL, PARSIM.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 26, 'Esta é a interpretação daquilo: MENE: Contou Deus o teu reino, e o acabou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 27, 'TEQUEL: Pesado foste na balança, e foste achado em falta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 28, 'PERES: Dividido foi teu reino, e entregue aos a medos e aos persas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 29, 'Então Belsazar deu ordens, e vestiram a Daniel de púrpura, [puseram] uma corrente de ouro em seu pescoço, e anunciaram que ele seria o terceiro líder no reino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 30, 'Naquela mesma noite Belsazar, rei dos caldeus, foi morto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 5, 31, 'E Dario, o medo, tomou o reino, sendo da idade de sessenta e dois anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 6, 1, 'Pareceu bem a Dario constituir sobre o reino cento vinte governadores que estivessem em todo o reino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 6, 2, 'E sobre eles três supervisores, dos quais Daniel era um, a quem estes governadores deviam prestar contas, para que o rei não sofresse dano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 6, 3, 'Então o mesmo Daniel era superior a estes governadores e supervisores, porque nele havia um espírito extraordinário; por isso o rei pensava em constituí-lo sobre todo o reino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 6, 4, 'Então os supervisores e governadores procuravam achar alguma acusação contra Daniel a respeito do reino; mas não conseguiram achar acusação ou falta alguma, porque ele era fiel, e nenhum erro nem falta foi achada nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 6, 5, 'Então esses homens disseram: Não acharemos acusação alguma contra este Daniel, a não ser se a acharmos contra ele na lei de seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 6, 6, 'Então esses supervisores e governadores foram juntos ao rei, e lhe disseram assim: Ó rei Dario, vive para sempre!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 6, 7, 'Todos os supervisores do reino, os prefeitos, governadores, conselheiros e capitães, concordaram em sugerir a promulgação de um decreto real, e estabelecer um estatuto forte, que qualquer um que, no intervalo de trinta dias, fizer alguma petição a qualquer deus ou humano, a não ser a ti, ó rei, seja lançado na cova dos leões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 6, 8, 'Agora, ó rei, confirma o decreto, e assina a escritura, para que não se mude, conforme à lei dos medos e dos persas, que não se pode revogar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 6, 9, 'Por esta causa o rei Dario assinou o decreto por escrito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 6, 10, 'E Daniel, quando soube que a escritura estava assinada, entrou em sua casa, e com as janelas de seu quarto abertas, voltadas para Jerusalém, punha-se de joelhos três vezes ao dia, e orava, e confessava diante de seu Deus, assim como costumava fazer antes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 6, 11, 'Então aqueles homens se juntaram, e encontraram Daniel orando e suplicando diante de seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 6, 12, 'Então se aproximaram e falaram diante do rei acerca do decreto real: Por acaso não assinaste o decreto que todo aquele que pedir a qualquer deus ou humano no intervalo de trinta dias, a não ser a ti, ó rei, seja lançado na cova dos leões? O rei respondeu: Esta palavra é certa, conforme a lei dos medos e dos persas, que não se pode revogar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 6, 13, 'Então disseram diante do rei: Daniel, que é um dos cativos de Judá, não respeitou a ti, ó rei, nem ao decreto que assinaste; em vez disso três vezes ao dia ele faz sua oração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 6, 14, 'Quando o rei ouviu isso, pesou-lhe muito, e tentou pensar em como livrar Daniel; e até o pôr do sol trabalhou para livrá-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 6, 15, 'Então aqueles homens foram juntos ao rei, e disseram ao rei: Sabe, ó rei, que é a lei dos medos e dos persas, que nenhum decreto um ordenança que o rei estabeleceu pode ser mudada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 6, 16, 'Então o rei mandou trazerem a Daniel, e [o] lançaram na cova dos leões. E o rei falou a Daniel: O teu Deus, a quem tu serves continuamente, ele te livre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 6, 17, 'E foi trazida uma pedra, e foi posta sobre a abertura da cova, a qual o rei selou com seu anel, e com o anel de seus grandes, para que a sentença acerca de Daniel não fosse mudada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 6, 18, 'Então o rei foi a seu palácio, e passou a noite em jejum; não permitiu que lhe trouxessem instrumentos musicais diante de si, e ele perdeu o sono.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 6, 19, 'Então o rei se levantou pela manhã cedo, e foi depressa à cova dos leões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 6, 20, 'E chegando perto da cova, chamou a Daniel com voz triste; e o rei falou a Daniel: Daniel, servo do Deus vivente! O teus Deus, a quem tu continuamente serves, pôde te livrar dos leões?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 6, 21, 'Então Daniel falou ao rei: Ó rei, vive para sempre!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 6, 22, 'Meu Deus enviou seu anjo, que fechou a boca dos leões, para que não me fizessem dano; porque diante dele se achou inocência em mim; e também contra ti, ó rei, não cometi delito algum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 6, 23, 'Então o rei se alegrou muito por causa dele, e mandou tirar a Daniel da cova; assim Daniel foi tirado da cova, e nenhum dano se achou nele, pois havia confiado em seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 6, 24, 'Então o rei mandou trazerem aqueles homens que tinham acusado a Daniel, e foram lançados na cova dos leões, eles, seus filhos, e suas mulheres; e nem sequer haviam chegado ao fundo da cova, quando os leões os tomaram, e quebraram todos os seus ossos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 6, 25, 'Então o rei Dario escreveu a todos os povos, nações, e línguas, que moram em toda a terra: Paz vos seja multiplicada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 6, 26, 'De minha parte é feito um decreto, que em todo o domínio de meu reino, [todos] tremam e temam a presença do Deus de Daniel; porque ele é o Deus vivente, que permanece para sempre; seu reino não se pode destruir, e seu domínio [dura] até o fim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 6, 27, 'Ele resgata e livra, e faz sinais e maravilhas no céu e na terra; ele livrou a Daniel do poder dos leões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 6, 28, 'E este Daniel foi próspero no reino de Dario, e no reinado de Ciro, o persa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 7, 1, 'No primeiro ano de Belsazar, rei da Babilônia, Daniel viu um sonho, e visões de sua cabeça em sua cama; logo escreveu o sonho, [e] anotou o resumo das coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 7, 2, 'Daniel disse: Eu estava vendo em minha visão de noite, e eis que os quatro ventos do céu atormentavam o grande mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 7, 3, 'E quatro grandes animais subiam do mar, diferentes um do outro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 7, 4, 'O primeiro era como leão, e tinha asas de águia. Eu estava olhando, até que suas asas lhe foram arrancadas; e foi levantado da terra; e posto de pé como um ser humano, e foi lhe dado um coração humano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 7, 5, 'E eis outra segundo animal, semelhante a um urso, a qual se levantou por um lado, e tinha em sua boca três costelas entre seus dentes; e foi lhe dito assim: Levanta-te, devora muita carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 7, 6, 'Depois disto eu estava olhando, e eis outro, semelhante a um leopardo, e tinha quatro asas de ave em suas costas; este animal também tinha quatro cabeças; e foi lhe dado domínio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 7, 7, 'Depois disto eu estava olhando nas visões da noite, e eis o quarta besta, terrível e espantoso, e muito forte. Ele tinha grandes dentes de ferro; devorava e quebrava em pedaços, e as sobras pisava com seus pés: e era diferente de todos os animais que foram antes dele; e tinha dez chifres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 7, 8, 'Enquanto eu estava observando os chifres, eis que outro chifre pequeno subia entre eles, e três dos primeiros chifres foram arrancados de diante dele; e eis que neste chifre havia olhos como olhos humanos, e uma boca que falava coisas arrogantes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 7, 9, 'Eu estive olhando até que foram postos tronos, e um Ancião de dias se sentou; sua veste era branca como a neve, e o cabelo de sua cabeça como lã limpa; seu trono era chamas de fogo, e suas rodas fogo ardente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 7, 10, 'Um rio de fogo manava e saía de diante dele; milhares de milhares lhe serviam, e milhões de milhões estavam de pé diante dele: o julgamento começou, e os livros foram abertos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 7, 11, 'Então eu estive olhando por causa da voz das palavras arrogantes que o chifre falava; estive olhando, até que mataram o animal, e seu corpo foi destruído, e entregue para ser queimado no fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 7, 12, 'E quanto aos outros animais, seu domínio foi tirado; porém lhes fora dada prolongação de vida até um certo tempo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 7, 13, 'Eu estava vendo em minhas visões de noite, e eis que estava vindo nas nuvens do céu como um filho do homem; e ele chegou até o Ancião de dias, e o fizeram chegar diante dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 7, 14, 'E foi lhe dado domínio, honra, e reino, de modo que todos os povos, nações e línguas lhe serviram; seu domínio é um domínio eterno, que não passará, e seu reino não será destruído.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 7, 15, 'Quanto a mim, Daniel, meu espírito foi perturbado dentro do corpo, e as visões de minha cabeça me espantaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 7, 16, 'Cheguei-me a um dos que estavam em pé, e lhe perguntei a verdade acerca de tudo isto. E ele me disse, e me fez saber a interpretação das coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 7, 17, 'Estas grandes animais, que são quatro, são quatro reis, que se levantarão da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 7, 18, 'Mas os santos do Altíssimo receberão o reino; e possuirão o reino para todo o sempre, eternamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 7, 19, 'Então tive desejo de saber a verdade acerca do quarto animal, que era tão diferente de todos os outros, muito terrível, que tinha dentes de ferro, e unhas de bronze, que devorava, quebrava em pedaços, e as sobras pisava com seus pés;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 7, 20, 'Assim como dos dez chifres que estavam em sua cabeça, e do outro que havia subido, de diante do qual três tinham caído; daquele chifre que tinha olhos, e boca que falava coisas arrogantes, e cuja aparência era maior que a de seus companheiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 7, 21, 'Eu estava vendo que este chifre fazia guerra contra os santos, e os vencia,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 7, 22, 'Até que veio o Ancião de dias, e o juízo foi dado em favor dos santos do Altíssimo; e veio o tempo que os santos possuíram o reino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 7, 23, 'Ele disse assim: O quarto animal será um quarto reino na terra, o qual será diferente de todos os reinos; e devorará toda a terra, e a pisará, e a quebrará em pedaços.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 7, 24, 'E os dez chifres [significam] que daquele reino se levantarão dez reis; e após deles se levantará outro, o qual será diferente dos primeiros, e humilhará a três reis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 7, 25, 'E falará palavras contra o Altíssimo, e destruirá os santos do Altíssimo; e pensará em mudar os tempos e a lei; e serão entregues em sua mão por um tempo, e tempos, e metade de um tempo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 7, 26, 'Porém o julgamento começará, e tirarão seu domínio, para que seja destruído e aniquilado até o fim;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 7, 27, 'E o reino, o domínio, e a majestade dos reinos debaixo de todo o céu, será dado ao povo dos santos do Altíssimo; seu reino será um reino eterno, e todos os domínios lhe servirão e obedecerão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 7, 28, 'Até aqui foi o fim do relato. Quanto a mim, Daniel, meus pensamentos me espantavam muito, e mudou-se meu semblante em mim; mas guardei o relato em meu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 8, 1, 'No terceiro ano do reinado do rei Belsazar, apareceu uma visão a mim, Daniel, depois daquela que tinha me aparecido no princípio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 8, 2, 'E vi em uma visão, (e aconteceu quando vi, que eu estava na fortaleza de Susã, que é na província de Elão) vi pois em uma visão, enquanto eu estava junto ao rio Ulai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 8, 3, 'E levantei meus olhos, e vi, e eis um carneiro que estava diante do rio, o qual tinha dois chifres; e os dois chifres eram altos, porém um era mais alto que o outro; e o mais alto subiu por último.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 8, 4, 'Vi que o carneiro dava golpes com os chifres para o ocidente, para o norte, e para o sul; nenhum dos animais podia lhe resistir, nem havia quem se livrasse de seu poder; e fazia conforme sua vontade, e se engrandecia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 8, 5, 'E enquanto eu estava considerando, eis um bode que vinha do ocidente sobre a face de toda a terra, e ele não tocava a terra; e aquele bode tinha um chifre muito visível entre seus olhos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 8, 6, 'E ele veio até o carneiro que tinha os dois chifres, o qual eu havia visto que estava diante do rio, e correu contra ele com o ímpeto de sua força.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 8, 7, 'E o vi chegar junto ao carneiro, e irritou-se contra ele, feriu o carneiro, e quebrou seus dois chifres, pois não havia no carneiro força para resistir-lhe; então o derrubou por terra, e o pisou; não houve quem livrasse o carneiro de seu poder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 8, 8, 'E o bode se engrandeceu muito; porém, quando estava em sua [maior] força, aquele grande chifre foi quebrado, e em seu lugar subiram [outros] quatro muito visíveis, na direção dos quatro ventos do céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 8, 9, 'E de um deles saiu um chifre pequeno, o qual cresceu muito ao sul, ao oriente, e à [terra] formosa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 8, 10, 'E engrandeceu-se até o exército do céu; e lançou por terra a [alguns] do exército e das estrelas, e as pisou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 8, 11, 'Engrandeceu-se até contra o príncipe do exército, e por ele foi tirado o contínuo [sacrifício] , e o lugar de seu santuário foi derrubado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 8, 12, 'E por causa da transgressão, o exército [lhe] foi entregue, assim como o contínuo [sacrifício] ; e lançou a verdade em terra, e teve sucesso naquilo que fez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 8, 13, 'Depois ouvi um santo que falava; e outro santo disse ao que falava: Até quando [durará] a visão do contínuo [sacrifício] , e da transgressão assoladora, de modo que o santuário e o exército são entregues para serem pisoteados?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 8, 14, 'E ele me disse: Até duas mil e trezentas tardes e manhãs; e o santuário será purificado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 8, 15, 'E aconteceu que, tendo eu, Daniel visto a visão, e buscando entendê-la, eis que [alguém] semelhante a um homem se pôs diante de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 8, 16, 'E ouvi uma voz de homem entre as [margens] de Ulai, que gritou e disse: Gabriel, explica a visão a este.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 8, 17, 'Então ele veio para perto de onde eu estava; e quando ele veio, me assombrei, e caí sobre meu rosto. Porém ele me disse: Entende, filho do homem; porque esta visão será para o tempo do fim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 8, 18, 'E enquanto ele estava falando comigo, adormeci sobre meu rosto em terra; então ele me tocou, e fez ficar de pé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 8, 19, 'E disse: Eis que eu te farei saber o que irá acontecer no fim da ira; pois será no tempo certo, o fim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 8, 20, 'Aquele carneiro que viste com dois chifres, são os reis da Média e da Pérsia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 8, 21, 'Porém o bode peludo é o rei da Grécia; e o chifre grande que tinha entre seus olhos é o primeiro rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 8, 22, 'E quanto a ter sido quebrado, e terem surgido quatro em seu lugar, [significa] que quatro reinos surgirão daquela nação, mas não com a força dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 8, 23, 'E ao fim do império deles, quando os transgressores se acabarem, se levantará um rei de rosto feroz, e entendido em astúcias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 8, 24, 'E sua força ganhará vigor, mas não com sua própria força; e destruirá terrivelmente, e terá sucesso naquilo que fizer; e destruirá os fortes e o povo dos santos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 8, 25, 'E com sua inteligência fará prosperar o engano em seu poder; e em seu coração se engrandecerá, e com tranquilidade destruirá a muitos; e se levantará contra o Príncipe dos príncipes, porém sem mão será quebrantado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 8, 26, 'E a visão da tarde e a manhã que foi dita é verdadeira; tu, porém guarda em segredo a visão, porque é para muitos dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 8, 27, 'E eu, Daniel, enfraqueci, e fiquei doente por [alguns] dias; depois me levantei, e tratei dos negócios do do rei; porém continuei espantado acerca da visão, e não havia quem a entendesse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 9, 1, 'No ano primeiro de Dario, filho de Assuero, da nação dos medos, o qual foi posto por rei sobre o reino dos caldeus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 9, 2, 'No primeiro ano de seu reinado, eu, Daniel, entendi pelos livros o número de anos, dos quais o SENHOR falara ao profeta Jeremias, que havia de acabar a assolação de Jerusalém, era setenta anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 9, 3, 'Então dirigi meu rosto ao Senhor Deus, para [o] buscar com oração e rogos, em jejum, saco, e cinza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 9, 4, 'E orei ao SENHOR meu Deus, e declarei, dizendo: Ó Senhor, Deus grande e temível, que guarda o pacto e a misericórdia com os que o amam e guardam seus mandamentos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 9, 5, 'Nós pecamos, cometemos maldade; agimos perversamente, e fomos rebeldes, por termos nos desviado de teus mandamentos e de teus juízos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 9, 6, 'Não demos ouvido a teus servos, os profetas, que em teu nome falaram a nossos reis, nossos príncipes, nossos pais, e a todo o povo da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 9, 7, 'A ti, Senhor, pertence a justiça, mas a nós a vergonha de rosto, tal como hoje [estamos] ,todo homem de Judá, os moradores de Jerusalém, e todo Israel, os de perto e os de longe, em todas as terras para onde os tens lançado por causa de sua transgressão com que transgrediram contra ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 9, 8, 'Ó SENHOR, a nós [pertence] a vergonha de rosto, a nossos reis, nossos príncipes, e nossos pais; porque contra ti pecamos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 9, 9, 'Ao SENHOR nosso Deus, pertence a misericórdia e os perdões, ainda que contra ele tenhamos nos rebelado;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 9, 10, 'E não obedecemos à voz do SENHOR nosso Deus, para andar em suas leis, as quais ele nos deu por meio de seus servos os profetas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 27, 'Daniel', 'Dn', 9, 11, 'E todo Israel transgrediu tua lei, desviando-se para não ouvir tua voz; por isso a maldição, e o juramento que está escrito na lei de Moisés, servo de Deus, foram derramados sobre nós; porque contra ele pecamos.')
